UPDATE `command` SET `help` = 'Recruit-A-Friend commands:\n.raf <CharacterName> - Invite an online player to permanent recruitment (Accept/Decline).\n.raf status - Show your direct recruits and their qualification progress.\n.raf levels - Show stored level credits and check your selected player eligibility. Cross-faction recruitment and grants are allowed.\n.raf rewards - List rewards and their status for this realm.\n.raf claim [reward_id] - Retry deliveries or claim an eligible reward through in-game mail.\n.help raf - Show this command list.' WHERE `name` = 'raf';
